INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '41f939fa-c534-504f-b015-b8fc0c3d1320', '3cf00c29-8649-5463-ba40-e349d2dcdb8b',
  'Given the head of a doubly linked list, two positive integers `a` and `b` where `a <= b`. Reverse the nodes of the list from position `a` to position `b` and return the reversed list.

Note: the position of the first node is 1. It is guaranteed that `a` and `b` are valid positions. You MUST NOT change the `val` attribute in each node.

```cpp
struct ListNode {
    int val;
    ListNode *left;
    ListNode *right;
    ListNode(int x = 0, ListNode *l = nullptr, ListNode* r = nullptr) : val(x), left(l), right(r) {}
};
```

Constraint:

1. `1 <= list.length <= 10^5`
2. `0 <= node.val <= 5000`
3. `1 <= left <= right <= list.length`

Example 1:

- Input: `list = {3, 4, 5, 6, 7}, a = 2, b = 4`
- Output: `3 6 5 4 7`

Example 2:

- Input: `list = {8, 9, 10}, a = 1, b = 3`
- Output: `10 9 8`

Test example:

```cpp
int size;
cin >> size;
int* list = new int[size];
for(int i = 0; i < size; i++) {
    cin >> list[i];
}
int a, b;
cin >> a >> b;
unordered_map<ListNode*, int> nodeValue;
ListNode* head = init(list, size, nodeValue);
ListNode* reversed = reverse(head, a, b);
try {
    printList(reversed, nodeValue);
}
catch(char const* err) {
    cout << err << ''\n'';
}
freeMem(head);
delete[] list;
```

Test input:

```text
5
3 4 5 6 7
2 4
```

Result:

```text
3 6 5 4 7
```

Additional test:

```text
3
8 9 10
1 3
```

Result:

```text
10 9 8
```

Đáp án: ```cpp
/*
struct ListNode {
    int val;
    ListNode *left;
    ListNode *right;
    ListNode(int x = 0, ListNode *l = nullptr, ListNode* r = nullptr) : val
};
*/

typedef ListNode* ptr;
ListNode* reverse(ListNode* head, int a, int b) {
    int idx = 0;
    ptr b_ptr = head;
    while (b_ptr != NULL)
    {
        if (idx == b) break;
        b_ptr = b_ptr->right;
        ++idx;
    }
    ptr a_ptr = head;
    idx = 0;
    while (a_ptr != NULL)
    {
        if (idx == a) break;
        a_ptr = a_ptr->right;
        ++idx;
    }
    a_ptr->left->right = b_ptr;
    for (int i = b; i >= a; --i)
    {
        b_ptr->right = b_ptr->left;
        b_ptr = b_ptr->left;
    }
    return head;
}
```', 2
);

