  '0ccfdb6d-8bf2-53b5-80a0-2777b9771456', '3cf00c29-8649-5463-ba40-e349d2dcdb8b',
  'Given a string `s` containing just the characters `''(''`, `'')''`, `''[''`, `'']''`, `''{''`, and `''}''`. Check if the input string is valid based on the following rules:

1. Open brackets must be closed by the same type of brackets.
2. Open brackets must be closed in the correct order.

For example:

- String `"[]()"` is a valid string, also `"()"`.
- String `"[]"` is not a valid string.

Your task is to implement the function:

```cpp
bool isValidParentheses (string s){
    /*TODO*/
}
```

**For example:**

| Test | Result |
| :--- | :--- |
| `cout << isValidParentheses("()");` | `1` |
| `cout << isValidParentheses("[]()");` | `1` |
| `cout << isValidParentheses("[]");` | `0` |

Đáp án: ```cpp
bool isValidParentheses(string s)
{
    stack<char> stk;
    char x;

    // Traversing the Expression
    for (int i = 0; i < (int)s.length(); i++)
    {
        if (s[i] == ''('' || s[i] == ''[''
            || s[i] == ''{'')
        {
            // Push the element in the stack
            stk.push(s[i]);
            continue;
        }

        // IF current current character is not opening
        // bracket, then it must be closing. So stack
        // cannot be empty at this point.
        if (stk.empty())
            return false;

        switch (s[i]) {
        case '')'':
            // Store the top element in a
            x = stk.top();
            stk.pop();
            if (x == ''{'' || x == ''['')
                return false;
            break;

        case ''}'':

35     // Store the top element in b
36     x = stk.top();
37     stk.pop();
38     if (x == ''('' || x == ''['')
39         return false;
40     break;
41
42     case '']'':

44         // Store the top element in c
45         x = stk.top();
46         stk.pop();
47         if (x == ''('' || x == ''{'')
48             return false;
49         break;
50     }
51 }
52
53 // Check Empty Stack
54 return (stk.empty());
55 }
```', 4
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '43dae88c-2360-5cf8-9f09-290a3fa7136f', '3cf00c29-8649-5463-ba40-e349d2dcdb8b',
  'Given an array `nums[]` of size `N`, the task is to find the next greater element for each element of the array.

The next greater element of an element in the array is the nearest element on the right which is greater than the current element. If there does not exist a next greater element, the next greater element for it is `-1`.

Note: `iostream`, `stack` and `vector` are already included.

Constraints:

- `1 <= nums.length <= 10^5`
- `0 <= nums[i] <= 10^9`

Example 1:

Input:
`nums = {15, 2, 4, 10}`

Output:
`{-1, 4, 10, -1}`

Example 2:

Input:
`nums = {1, 4, 6, 9, 6}`

Output:
`{4, 6, 9, -1, -1}`

For example:

| Test | Input | Result |
| :--- | :--- | :--- |
| ```cpp
int N;
cin >> N;
vector<int> nums(N);
for(int i = 0; i < N; i++) cin >> nums[i];
vector<int> greaterNums = nextGreater(nums);
for(int i : greaterNums)
    cout << i << '' '';
cout << ''\\n'';
``` | `4`<br>`15 2 4 10` | `-1 4 10 -1` |
| ```cpp
int N;
cin >> N;
vector<int> nums(N);
for(int i = 0; i < N; i++) cin >> nums[i];
vector<int> greaterNums = nextGreater(nums);
for(int i : greaterNums)
    cout << i << '' '';
cout << ''\\n'';
``` | `5`<br>`1 4 6 9 6` | `4 6 9 -1 -1` |

Đáp án: ```cpp
vector<int> nextGreater(vector<int>& arr){
    stack<int> stk;
    int size = arr.size();
    for (int i = size - 1; i >= 0;  --i) stk.push(arr[i]);
    for (int i = 0; i < size- 1; ++i)
    {
        for (int j = i+1; j < size; ++j)
        {
            if (arr[j] > stk.top() ) {arr[i] = arr[j]; break;}
            else
            {
                if (j == size -1 ) arr[i] = -1;
            }
        }
        stk.pop();
    }
    arr[arr.size()-1] = -1;
    return arr;
}
```', 5
);

